'EPIC-008'; from pathlib import Path; import yaml; from infra2_sdk.manifests import load_hooks_manifest; ROOT = Path(__file__).resolve().parents[2]; _load = lambda path: yaml.safe_load((ROOT / path).read_text(encoding='utf-8')); _workflow_on = lambda wf: wf.get(True) or wf.get('on') or {}; _TRIGGER_ON_KEY = {'pull_request': 'pull_request', 'workflow_run': 'workflow_run', 'workflow_dispatch': 'workflow_dispatch', 'workflow_call': 'workflow_call', 'tag': 'push'}; GATES = _load('common/meta/data/delivery-gates.yaml')['gates']
from tests.tooling.hook_text import hook_text
def test_every_gate_workflow_declares_its_manifest_trigger():
    hooks = load_hooks_manifest(ROOT / 'runtime-hooks.manifest.json').slots
    for gate in GATES:
        if gate['workflow'] == 'runtime-hooks.manifest.json': assert gate['job'] in hooks, f"gate {gate['id']!r} references hook slot {gate['job']!r} not in runtime-hooks.manifest.json"; continue
        on = _workflow_on(_load(gate['workflow'])); key = _TRIGGER_ON_KEY[gate['trigger']]; assert key in on, f"gate {gate['id']!r} declares trigger={gate['trigger']} but {gate['workflow']} `on:` has no `{key}` (delivery-gates.yaml is the SSOT)."
        if gate['trigger'] == 'tag': assert (on.get('push') or {}).get('tags'), f"gate {gate['id']!r} is tag-triggered but on.push has no tags filter."
    _m1_ci_wf = _load('.github/workflows/ci.yml'); assert 'pull_request' in _workflow_on(_m1_ci_wf); _m1_finish = (_m1_ci_wf.get('jobs') or {}).get('finish'); assert isinstance(_m1_finish, dict); assert _m1_finish.get('needs'); _m2_gate = next((_m2_g for _m2_g in GATES if _m2_g['id'] == 'staging-benchmark')); assert _m2_gate['workflow'] == 'runtime-hooks.manifest.json'; assert _m2_gate['job'] == 'scheduled_audit'; assert _m2_gate['blocking'] is True; _m2_hooks = load_hooks_manifest(ROOT / 'runtime-hooks.manifest.json').slots; assert '--corpus audit_replay' in hook_text(_m2_hooks['scheduled_audit']); _m3_hooks = load_hooks_manifest(ROOT / 'runtime-hooks.manifest.json').slots
    for _m3_gate in GATES:
        if _m3_gate['workflow'] == 'runtime-hooks.manifest.json': assert _m3_gate['job'] in _m3_hooks, f"gate {_m3_gate['id']!r} references hook slot {_m3_gate['job']!r} not in {_m3_gate['workflow']}."; continue
        _m3_jobs = _load(_m3_gate['workflow']).get('jobs') or {}; assert _m3_gate['job'] in _m3_jobs, f"gate {_m3_gate['id']!r} references job {_m3_gate['job']!r} not in {_m3_gate['workflow']}."
